import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    def get_int():
        return int(next(iterator))

    x1, y1, x2, y2 = get_int(), get_int(), get_int(), get_int()
    x3, y3, x4, y4 = get_int(), get_int(), get_int(), get_int()
    x5, y5, x6, y6 = get_int(), get_int(), get_int(), get_int()

    # Function to calculate intersection of two rectangles
    def intersect(xa, ya, xb, yb, xc, yc, xd, yd):
        ix = max(xa, xc)
        iy = max(ya, yc)
        fx = min(xb, xd)
        fy = min(yb, yd)
        if ix < fx and iy < fy:
            return (ix, iy, fx, fy)
        return None

    # Function to calculate area of a rectangle
    def area(xa, ya, xb, yb):
        return (xb - xa) * (yb - ya)

    # Calculate area of white sheet
    w_area = area(x1, y1, x2, y2)

    # Calculate intersection of white with black1
    i1 = intersect(x1, y1, x2, y2, x3, y3, x4, y4)
    # Calculate intersection of white with black2
    i2 = intersect(x1, y1, x2, y2, x5, y5, x6, y6)

    # Calculate intersection of the two black sheets
    b1b2 = intersect(x3, y3, x4, y4, x5, y5, x6, y6)

    # Calculate area covered by black1 within white
    if i1:
        covered_by_b1 = area(i1[0], i1[1], i1[2], i1[3])
    else:
        covered_by_b1 = 0

    # Calculate area covered by black2 within white
    if i2:
        covered_by_b2 = area(i2[0], i2[1], i2[2], i2[3])
    else:
        covered_by_b2 = 0

    # Calculate area covered by both black sheets within white (intersection of i1 and i2)
    # The intersection of the parts of black1 and black2 that are inside white is simply the intersection of i1 and i2
    i1i2 = intersect(i1[0], i1[1], i1[2], i1[3], i2[0], i2[1], i2[2], i2[3]) if i1 and i2 else None
    if i1i2:
        covered_by_both = area(i1i2[0], i1i2[1], i1i2[2], i1i2[3])
    else:
        covered_by_both = 0

    # Total covered area = area(B1 in W) + area(B2 in W) - area(B1 intersect B2 in W)
    total_covered = covered_by_b1 + covered_by_b2 - covered_by_both

    if total_covered == w_area:
        print("NO")
    else:
        print("YES")

if __name__ == "__main__":
    solve()
